// Step 1: Parse the Slack message from GROWI global notification
// Extract editor username and page ID/path from the message text

const body = $input.first().json.body || $input.first().json;
const text = body.text || '';

// Pattern: :bell: <siteUrl/user/USERNAME|USERNAME> edited <siteUrl/PAGE_ID|PAGE_PATH>
const editorMatch = text.match(/<[^|]+\/user\/([^|>]+)\|/);
const pageMatch = text.match(/edited\s+<([^|]+)\|([^>]+)>/);

if (!editorMatch || !pageMatch) {
  // Not a page edit notification, skip
  return [];
}

const editor = editorMatch[1];
const pageUrl = pageMatch[1];
const pagePath = pageMatch[2];

// Extract page ID from URL (last path segment)
const pageId = pageUrl.split('/').pop();

// Extract GROWI base URL
const baseUrl = pageUrl.replace(new RegExp('/' + pageId + '$'), '');

return [{
  json: {
    editor,
    pageId,
    pagePath,
    pageUrl,
    baseUrl,
    originalText: text
  }
}];

