// Step 2: Compute diff between revisions and extract @mentions

const input = $input.first().json;
const revisions = input.revisions || input.data?.revisions || [];
const prevItem = $('Parse Notification').first().json;
const editor = prevItem.editor;
const pagePath = prevItem.pagePath;
const pageUrl = prevItem.pageUrl;
const baseUrl = prevItem.baseUrl;

if (revisions.length === 0) {
  return [];
}

const currentBody = revisions[0]?.body || '';
const previousBody = revisions.length > 1 ? (revisions[1]?.body || '') : '';

// --- Diff computation ---
// Split into lines and find added lines
const prevLines = new Set(previousBody.split('\n'));
const currentLines = currentBody.split('\n');
const addedLines = currentLines.filter(line => !prevLines.has(line));
const diffText = addedLines.join('\n');

// --- Extract @mentions from diff ---
const mentionPattern = /\B@[\w@.-]+/g;
const mentions = diffText.match(mentionPattern) || [];
const mentionedUsernames = [...new Set(mentions.map(m => m.slice(1)))];

// --- Extract contributors from revision authors ---
const contributors = [...new Set(
  revisions
    .map(r => r.author?.username)
    .filter(u => u != null)
)];

// --- Extract page owner (first revision author = creator) ---
// Note: With only 2 revisions we may not have the creator.
// The page creator info would need a separate API call if needed.

// --- Combine all targets, deduplicate, exclude the editor ---
const allTargets = [...new Set([...contributors, ...mentionedUsernames])]
  .filter(u => u !== editor);

if (allTargets.length === 0) {
  return [];
}

// Build notification message
const message = `📝 @${editor} が [${pagePath}](${pageUrl}) を編集しました\n`
  + `👥 関係者: ${allTargets.map(u => '@' + u).join(' ')}`;

const mentionOnlyTargets = mentionedUsernames.filter(u => u !== editor);

return [{
  json: {
    editor,
    pagePath,
    pageUrl,
    baseUrl,
    diffText,
    mentionedUsernames: mentionOnlyTargets,
    contributors: contributors.filter(u => u !== editor),
    allTargets,
    message
  }
}];

// Split each target user into a separate item for individual notification
const input = $input.first().json;

return input.allTargets.map(username => ({
  json: {
    targetUsername: username,
    editor: input.editor,
    pagePath: input.pagePath,
    pageUrl: input.pageUrl,
    baseUrl: input.baseUrl,
    message: input.message,
    isMentioned: input.mentionedUsernames.includes(username),
    isContributor: input.contributors.includes(username)
  }
}));
